@Test
public void testIsometry() {
    // arrange
    Vector3D vertex1 = Vector3D.of(1.1, 2.2, 3.3);
    Vector3D vertex2 = Vector3D.of(2.0, 2.4, 4.2);
    Vector3D vertex3 = Vector3D.of(2.8, 3.3, 3.7);
    Vector3D vertex4 = Vector3D.of(1.0, 3.6, 4.5);
    // act
    PolyhedronsSet tree = (PolyhedronsSet) new RegionFactory<Vector3D>().buildConvex(new Plane(vertex3, vertex2, vertex1, TEST_TOLERANCE), new Plane(vertex2, vertex3, vertex4, TEST_TOLERANCE), new Plane(vertex4, vertex3, vertex1, TEST_TOLERANCE), new Plane(vertex1, vertex2, vertex4, TEST_TOLERANCE));
    // assert
    Vector3D barycenter = tree.getBarycenter();
    Vector3D s = Vector3D.of(10.2, 4.3, -6.7);
    Vector3D c = Vector3D.of(-0.2, 2.1, -3.2);
    QuaternionRotation r = QuaternionRotation.fromAxisAngle(Vector3D.of(6.2, -4.4, 2.1), 0.12);
    tree = tree.rotate(c, r).translate(s);
    Vector3D newB = Vector3D.linearCombination(1.0, s, 1.0, c, 1.0, r.apply(barycenter.subtract(c)));
    Assert.assertEquals(0.0, newB.subtract(tree.getBarycenter()).norm(), TEST_TOLERANCE);
    final Vector3D[] expectedV = new Vector3D[] { Vector3D.linearCombination(1.0, s, 1.0, c, 1.0, r.apply(vertex1.subtract(c))), Vector3D.linearCombination(1.0, s, 1.0, c, 1.0, r.apply(vertex2.subtract(c))), Vector3D.linearCombination(1.0, s, 1.0, c, 1.0, r.apply(vertex3.subtract(c))), Vector3D.linearCombination(1.0, s, 1.0, c, 1.0, r.apply(vertex4.subtract(c))) };
    tree.getTree(true).visit(new BSPTreeVisitor<Vector3D>() {

        @Override
        public Order visitOrder(BSPTree<Vector3D> node) {
            return Order.MINUS_SUB_PLUS;
        }

        @Override
        public void visitInternalNode(BSPTree<Vector3D> node) {
            @SuppressWarnings("unchecked")
            BoundaryAttribute<Vector3D> attribute = (BoundaryAttribute<Vector3D>) node.getAttribute();
            if (attribute.getPlusOutside() != null) {
                checkFacet((SubPlane) attribute.getPlusOutside());
            }
            if (attribute.getPlusInside() != null) {
                checkFacet((SubPlane) attribute.getPlusInside());
            }
        }

        @Override
        public void visitLeafNode(BSPTree<Vector3D> node) {
        }

        private void checkFacet(SubPlane facet) {
            Plane plane = (Plane) facet.getHyperplane();
            Vector2D[][] vertices = ((PolygonsSet) facet.getRemainingRegion()).getVertices();
            Assert.assertEquals(1, vertices.length);
            for (int i = 0; i < vertices[0].length; ++i) {
                Vector3D v = plane.toSpace(vertices[0][i]);
                double d = Double.POSITIVE_INFINITY;
                for (int k = 0; k < expectedV.length; ++k) {
                    d = Math.min(d, v.subtract(expectedV[k]).norm());
                }
                Assert.assertEquals(0, d, TEST_TOLERANCE);
            }
        }
    });
}

