@Test
public void testCrossProduct_nearlyAntiParallel() {
    // the vectors u1 and u2 are nearly but not exactly anti-parallel
    // (7.31e-16 degrees from 180 degrees) naive cross product (i.e.
    // computing u1.x * u2.x + u1.y * u2.y + u1.z * u2.z
    // leads to a result of   [0.0009765, -0.0001220, -0.0039062],
    // instead of the correct [0.0006913, -0.0001254, -0.0007909]
    // arrange
    final Vector3D u1 = Vector3D.of(-1321008684645961.0 / 268435456.0, -5774608829631843.0 / 268435456.0, -7645843051051357.0 / 8589934592.0);
    final Vector3D u2 = Vector3D.of(1796571811118507.0 / 2147483648.0, 7853468008299307.0 / 2147483648.0, 2599586637357461.0 / 17179869184.0);
    final Vector3D u3 = Vector3D.of(12753243807587107.0 / 18446744073709551616.0, -2313766922703915.0 / 18446744073709551616.0, -227970081415313.0 / 288230376151711744.0);
    // act
    Vector3D cNaive = Vector3D.of(u1.getY() * u2.getZ() - u1.getZ() * u2.getY(), u1.getZ() * u2.getX() - u1.getX() * u2.getZ(), u1.getX() * u2.getY() - u1.getY() * u2.getX());
    Vector3D cAccurate = u1.cross(u2);
    // assert
    Assert.assertTrue(u3.distance(cNaive) > 2.9 * u3.norm());
    Assert.assertEquals(0.0, u3.distance(cAccurate), 1.0e-30 * cAccurate.norm());
}

