    GeometryTestUtils.assertThrows(() -> {
        AffineTransformMatrix2D.of(1, 0, 0, 0, Double.NEGATIVE_INFINITY, 0).inverse();
    }, NonInvertibleTransformException.class, "Transform is not invertible; matrix determinant is -Infinity");
    GeometryTestUtils.assertThrows(() -> {
        AffineTransformMatrix2D.of(Double.POSITIVE_INFINITY, 0, 0, 0, 1, 0).inverse();
    }, NonInvertibleTransformException.class, "Transform is not invertible; matrix determinant is Infinity");
    GeometryTestUtils.assertThrows(() -> {
        AffineTransformMatrix2D.of(1, 0, Double.NaN, 0, 1, 0).inverse();
    }, NonInvertibleTransformException.class, "Transform is not invertible; invalid matrix element: NaN");
    GeometryTestUtils.assertThrows(() -> {
        AffineTransformMatrix2D.of(1, 0, Double.POSITIVE_INFINITY, 0, 1, 0).inverse();
    }, NonInvertibleTransformException.class, "Transform is not invertible; invalid matrix element: Infinity");
    GeometryTestUtils.assertThrows(() -> {
        AffineTransformMatrix2D.of(1, 0, Double.NEGATIVE_INFINITY, 0, 1, 0).inverse();
    }, NonInvertibleTransformException.class, "Transform is not invertible; invalid matrix element: -Infinity");
}

