@Test
public void testHole() {
    // arrange
    Vector2D[][] vertices = new Vector2D[][] { new Vector2D[] { Vector2D.of(0.0, 0.0), Vector2D.of(3.0, 0.0), Vector2D.of(3.0, 3.0), Vector2D.of(0.0, 3.0) }, new Vector2D[] { Vector2D.of(1.0, 2.0), Vector2D.of(2.0, 2.0), Vector2D.of(2.0, 1.0), Vector2D.of(1.0, 1.0) } };
    // act
    PolygonsSet set = buildSet(vertices);
    // assert
    checkPoints(Region.Location.INSIDE, set, new Vector2D[] { Vector2D.of(0.5, 0.5), Vector2D.of(1.5, 0.5), Vector2D.of(2.5, 0.5), Vector2D.of(0.5, 1.5), Vector2D.of(2.5, 1.5), Vector2D.of(0.5, 2.5), Vector2D.of(1.5, 2.5), Vector2D.of(2.5, 2.5), Vector2D.of(0.5, 1.0) });
    checkPoints(Region.Location.OUTSIDE, set, new Vector2D[] { Vector2D.of(1.5, 1.5), Vector2D.of(3.5, 1.0), Vector2D.of(4.0, 1.5), Vector2D.of(6.0, 6.0) });
    checkPoints(Region.Location.BOUNDARY, set, new Vector2D[] { Vector2D.of(1.0, 1.0), Vector2D.of(1.5, 0.0), Vector2D.of(1.5, 1.0), Vector2D.of(1.5, 2.0), Vector2D.of(1.5, 3.0), Vector2D.of(3.0, 3.0) });
    checkVertexLoopsEquivalent(vertices, set.getVertices());
    for (double x = -0.999; x < 3.999; x += 0.11) {
        Vector2D v = Vector2D.of(x, x + 0.5);
        BoundaryProjection<Vector2D> projection = set.projectToBoundary(v);
        Assert.assertTrue(projection.getOriginal() == v);
        Vector2D p = projection.getProjected();
        if (x < -0.5) {
            Assert.assertEquals(0.0, p.getX(), TEST_TOLERANCE);
            Assert.assertEquals(0.0, p.getY(), TEST_TOLERANCE);
            Assert.assertEquals(+v.distance(Vector2D.ZERO), projection.getOffset(), TEST_TOLERANCE);
        } else if (x < 0.5) {
            Assert.assertEquals(0.0, p.getX(), TEST_TOLERANCE);
            Assert.assertEquals(v.getY(), p.getY(), TEST_TOLERANCE);
            Assert.assertEquals(-v.getX(), projection.getOffset(), TEST_TOLERANCE);
        } else if (x < 1.25) {
            Assert.assertEquals(1.0, p.getX(), TEST_TOLERANCE);
            Assert.assertEquals(v.getY(), p.getY(), TEST_TOLERANCE);
            Assert.assertEquals(v.getX() - 1.0, projection.getOffset(), TEST_TOLERANCE);
        } else if (x < 2.0) {
            Assert.assertEquals(v.getX(), p.getX(), TEST_TOLERANCE);
            Assert.assertEquals(2.0, p.getY(), TEST_TOLERANCE);
            Assert.assertEquals(2.0 - v.getY(), projection.getOffset(), TEST_TOLERANCE);
        } else if (x < 3.0) {
            Assert.assertEquals(v.getX(), p.getX(), TEST_TOLERANCE);
            Assert.assertEquals(3.0, p.getY(), TEST_TOLERANCE);
            Assert.assertEquals(v.getY() - 3.0, projection.getOffset(), TEST_TOLERANCE);
        } else {
            Assert.assertEquals(3.0, p.getX(), TEST_TOLERANCE);
            Assert.assertEquals(3.0, p.getY(), TEST_TOLERANCE);
            Assert.assertEquals(+v.distance(Vector2D.of(3, 3)), projection.getOffset(), TEST_TOLERANCE);
        }
    }
}

