@Test
public void testChoppedHexagon() {
    // arrange
    double pi6 = Math.PI / 6.0;
    double sqrt3 = Math.sqrt(3.0);
    SubLine[] hyp = { new Line(Vector2D.of(0.0, 1.0), 5 * pi6, TEST_TOLERANCE).wholeHyperplane(), new Line(Vector2D.of(-sqrt3, 1.0), 7 * pi6, TEST_TOLERANCE).wholeHyperplane(), new Line(Vector2D.of(-sqrt3, 1.0), 9 * pi6, TEST_TOLERANCE).wholeHyperplane(), new Line(Vector2D.of(-sqrt3, 0.0), 11 * pi6, TEST_TOLERANCE).wholeHyperplane(), new Line(Vector2D.of(0.0, 0.0), 13 * pi6, TEST_TOLERANCE).wholeHyperplane(), new Line(Vector2D.of(0.0, 1.0), 3 * pi6, TEST_TOLERANCE).wholeHyperplane(), new Line(Vector2D.of(-5.0 * sqrt3 / 6.0, 0.0), 9 * pi6, TEST_TOLERANCE).wholeHyperplane() };
    hyp[1] = (SubLine) hyp[1].split(hyp[0].getHyperplane()).getMinus();
    hyp[2] = (SubLine) hyp[2].split(hyp[1].getHyperplane()).getMinus();
    hyp[3] = (SubLine) hyp[3].split(hyp[2].getHyperplane()).getMinus();
    hyp[4] = (SubLine) hyp[4].split(hyp[3].getHyperplane()).getMinus().split(hyp[0].getHyperplane()).getMinus();
    hyp[5] = (SubLine) hyp[5].split(hyp[4].getHyperplane()).getMinus().split(hyp[0].getHyperplane()).getMinus();
    hyp[6] = (SubLine) hyp[6].split(hyp[3].getHyperplane()).getMinus().split(hyp[1].getHyperplane()).getMinus();
    BSPTree<Vector2D> tree = new BSPTree<>(Boolean.TRUE);
    for (int i = hyp.length - 1; i >= 0; --i) {
        tree = new BSPTree<>(hyp[i], new BSPTree<Vector2D>(Boolean.FALSE), tree, null);
    }
    PolygonsSet set = new PolygonsSet(tree, TEST_TOLERANCE);
    SubLine splitter = new Line(Vector2D.of(-2.0 * sqrt3 / 3.0, 0.0), 9 * pi6, TEST_TOLERANCE).wholeHyperplane();
    // act
    PolygonsSet slice = new PolygonsSet(new BSPTree<>(splitter, set.getTree(false).split(splitter).getPlus(), new BSPTree<Vector2D>(Boolean.FALSE), null), TEST_TOLERANCE);
    // assert
    Assert.assertEquals(Region.Location.OUTSIDE, slice.checkPoint(Vector2D.of(0.1, 0.5)));
    Assert.assertEquals(11.0 / 3.0, slice.getBoundarySize(), TEST_TOLERANCE);
}

